// 0.46.3: формы Word встроенного шаблона «Камчатка» (по образцам заказчика, с метками {Группа.Поле}): АОСР,
// реестр примененных материалов, реестр приложений. Сгенерировано из образцов — правка только заменой файла.

const AOSR =
  "";
const RIM =
  "";
const RP =
  "";

/** Форма Word документа «Камчатки» (null — документ печатается только встроенной формой: ВД и КЖ — в Excel). */
export function kamDocx(kind: string): Buffer | null {
  const b64 = kind === "aosr" ? AOSR : kind === "rim" ? RIM : kind === "rp" ? RP : null;
  return b64 ? Buffer.from(b64, "base64") : null;
}
